svg.script:
        let isOpen = false;

        function toggleMenu() {
            const top = document.getElementById("top");
            const middle = document.getElementById("middle");
            const bottom = document.getElementById("bottom");

            if (!isOpen) {

                top.animate(
                    [
                        { d: "path('M 4 7 L 28 7')" },
                        { d: "path('M 5 5 L 27 27')" }
                    ],
                    {
                        duration: 250,
                        fill: "forwards"
                    }
                );

                middle.animate(
                    [
                        { opacity: 1 },
                        { opacity: 0 }
                    ],
                    {
                        duration: 150,
                        fill: "forwards"
                    }
                );

                bottom.animate(
                    [
                        { d: "path('M 4 25 L 28 25')" },
                        { d: "path('M 5 27 L 27 5')" }
                    ],
                    {
                        duration: 250,
                        fill: "forwards"
                    }
                );

                isOpen = true;

            } else {

                top.animate(
                    [
                        { d: "path('M 5 5 L 27 27')" },
                        { d: "path('M 4 7 L 28 7')" }
                    ],
                    {
                        duration: 250,
                        fill: "forwards"
                    }
                );

                middle.animate(
                    [
                        { opacity: 0 },
                        { opacity: 1 }
                    ],
                    {
                        duration: 150,
                        fill: "forwards"
                    }
                );

                bottom.animate(
                    [
                        { d: "path('M 5 27 L 27 5')" },
                        { d: "path('M 4 25 L 28 25')" }
                    ],
                    {
                        duration: 250,
                        fill: "forwards"
                    }
                );

                isOpen = false;
            }
        }

        document.querySelector("svg").addEventListener("click", toggleMenu);
